using System.ComponentModel.DataAnnotations;
namespace RaceDay.Web;
public class RegisterViewModel { [Required] public string Username { get; set; } = ""; [Required, EmailAddress] public string Email { get; set; } = ""; [Required, MinLength(8), DataType(DataType.Password)] public string Password { get; set; } = ""; [Required] public string Role { get; set; } = "Participant"; public string? OrganisationName { get; set; } public string? ContactName { get; set; } public string? Phone { get; set; } public string? FirstName { get; set; } public string? LastName { get; set; } public DateOnly? DateOfBirth { get; set; } public string? Gender { get; set; } public string? EmergencyContact { get; set; } }
public class EventViewModel { public int EventId { get; set; } [Required] public string EventName { get; set; } = ""; [Required] public string Description { get; set; } = ""; public DateOnly EventDate { get; set; } = DateOnly.FromDateTime(DateTime.Today); [Required] public string Location { get; set; } = ""; [Range(.1,1000)] public decimal Distance { get; set; } [Required] public string EventType { get; set; } = "run"; public string? Status { get; set; } = "Open"; public string? BannerImageUrl { get; set; } public IFormFile? Banner { get; set; } }
public class CategoryViewModel { public int CategoryId { get; set; } [Required] public string CategoryName { get; set; } = ""; [Range(.1,1000)] public decimal Distance { get; set; } [Range(0,120)] public int MinAge { get; set; } [Range(0,120)] public int MaxAge { get; set; } [Range(0,100000)] public decimal EntryFee { get; set; } }
public class ResultViewModel { public int EnrollmentId { get; set; } public TimeOnly FinishTime { get; set; } [Range(1,int.MaxValue)] public int Position { get; set; } public string? Remarks { get; set; } }
public class ProfileViewModel { public string? FirstName { get; set; } public string? LastName { get; set; } public DateOnly? DateOfBirth { get; set; } public string? Gender { get; set; } public string? EmergencyContact { get; set; } public string? ProfilePictureUrl { get; set; } public IFormFile? Picture { get; set; } }
